#!/usr/bin/env python3
"""omics/multimodal_wnn — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "omics"
SKILL = "multimodal_wnn"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'multimodal_wnn', 'matrix_path': '', 'n_cells_post_qc': 0, 'cluster_sizes': {}, 'marker_genes_per_cluster': {}, 'umap_png': '', 'diagnostics': {'brain': 'omics', 'archetype': 'omics_scrna'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """muon WNN (Weighted Nearest Neighbor) 多模态 integration (RNA + ATAC / CITE-seq)。
    host_env=praxis-omics (muon)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    rna_h5ad = payload.get("rna_h5ad")
    other_h5ad = payload.get("other_h5ad") or payload.get("adt_h5ad") or payload.get("atac_h5ad")
    out_h5mu = payload.get("out_h5mu") or _tempfile.NamedTemporaryFile(suffix="_mu.h5mu", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "muon.WNN", "out_h5mu": out_h5mu}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "matrix_path": "", "n_cells_post_qc": 0,
                "cluster_sizes": {}, "marker_genes_per_cluster": {}, "umap_png": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not rna_h5ad or not _os.path.isfile(rna_h5ad) or not other_h5ad or not _os.path.isfile(other_h5ad):
        return {"ok": False, "error": "需要 rna_h5ad + other_h5ad", "diagnostics": diagnostics}
    script = (
        "import json, sys, scanpy as sc, muon as mu\n"
        f"rna = sc.read_h5ad({rna_h5ad!r}); other = sc.read_h5ad({other_h5ad!r})\n"
        "mdata = mu.MuData({'rna': rna, 'other': other})\n"
        "for m in ['rna','other']:\n"
        "    sc.pp.normalize_total(mdata.mod[m]); sc.pp.log1p(mdata.mod[m])\n"
        "    sc.pp.scale(mdata.mod[m], max_value=10); sc.tl.pca(mdata.mod[m], n_comps=30)\n"
        "    sc.pp.neighbors(mdata.mod[m], n_neighbors=15)\n"
        "mu.pp.intersect_obs(mdata)\n"
        "mu.pp.neighbors(mdata, n_multiplex_neighbors=15)\n"
        "mu.tl.umap(mdata); mu.tl.leiden(mdata, resolution=0.6)\n"
        f"mdata.write({out_h5mu!r})\n"
        "cs = mdata.obs['leiden'].value_counts().to_dict() if 'leiden' in mdata.obs else {}\n"
        f"json.dump({{'matrix_path': {out_h5mu!r}, 'n_cells_post_qc': int(mdata.n_obs),\n"
        "           'cluster_sizes': {str(k):int(v) for k,v in cs.items()},\n"
        "           'marker_genes_per_cluster': {}}}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "muon WNN 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "umap_png": "",
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
